(1, 8, 'Bagan Cultural Escape', '3D2N Bagan cultural and sunset experience.', 245000.00, 3, '3-star hotel with breakfast', 'Private van / tour coach', 'Mandalay - Bagan - Mount Popa', 'Day 1 arrival and temple tour. Day 2 sunrise, lacquerware village, river sunset. Day 3 local market and return.', 'Hotel, breakfast, transport, guide, entrance support', 'Personal expense, lunch, dinner', NULL, 'active', '2026-04-09 12:06:46', '2026-04-09 12:06:46'),
(2, 8, 'Inle Lake Discovery', '2D1N lake discovery package with boat sightseeing.', 185000.00, 2, 'Boutique hotel with breakfast', 'Car + boat transfer', 'Taunggyi - Nyaung Shwe - Inle Lake', 'Day 1 travel and lake visit. Day 2 floating market and return.', 'Hotel, breakfast, boat fee, transport, guide', 'Personal expense, camera fee', 'uploads/tour_packages/tour_1782017295_1ebdb60f.jpg', 'active', '2026-04-09 12:06:46', '2026-06-21 04:48:15'),
(3, 8, 'Kalaw Nature Trek', '2D1N trekking and village experience.', 210000.00, 2, 'Guest house stay', 'Van + trekking support', 'Kalaw - Hill trail - Local village', 'Day 1 trek and cultural stop. Day 2 sunrise walk and return.', 'Transport, guide, snacks, stay', 'Personal expense', NULL, 'active', '2026-04-09 12:06:46', '2026-04-09 12:06:46'),
(4, 9, 'Yangon Heritage Walk', '1-day city heritage and downtown food stop tour.', 95000.00, 1, 'No hotel', 'City van + walking guide', 'Sule - Secretariat - Downtown Yangon', 'Morning city walk, colonial highlights, evening riverfront.', 'Guide, water, city transfer', 'Meals and personal expense', NULL, 'active', '2026-04-09 12:06:46', '2026-04-09 12:06:46'),
(5, 9, 'Mandalay Heritage Day Tour', 'One-day Mandalay city heritage exploration.', 98000.00, 1, 'No hotel', 'City van', 'Mandalay Palace - U Bein - Kuthodaw', 'Morning pickup, city highlights, sunset at U Bein bridge.', 'Transport, guide, water bottle', 'Meals and personal expense', NULL, 'active', '2026-04-09 12:06:46', '2026-04-09 12:06:46'),
(6, 9, 'Ngapali Beach Relax Package', '3D2N beach relaxation package.', 320000.00, 3, 'Beach resort with breakfast', 'Flight / express + local transfer', 'Yangon - Ngapali - Beach leisure', 'Relax, sightseeing, seafood dinner option, beach sunset.', 'Hotel, breakfast, airport/terminal transfer', 'Personal expense, optional water activities', NULL, 'active', '2026-04-09 12:06:46', '2026-04-09 12:06:46'),
(7, 10, 'Naypyidaw City Highlights', '1-day capital city exploration.', 110000.00, 1, 'No hotel', 'Private coach', 'Uppatasanti - Parliament area - Water fountain garden', 'Day trip with major capital landmarks and leisure stops.', 'Transport, guide, water', 'Meals and personal expense', NULL, 'active', '2026-04-09 12:06:46', '2026-04-09 12:06:46'),
(8, 13, 'Yangon Heritage Day Tour', 'Full-day downtown Yangon and pagoda highlights.', 95000.00, 1, 'No hotel', 'City van', 'Sule - Downtown - Shwedagon', 'Morning pickup, heritage walk, lunch stop, sunset at Shwedagon.', 'Transport, guide, water bottle', 'Meals and personal expense', NULL, 'active', '2026-04-09 12:29:49', '2026-04-09 12:29:49'),
(9, 13, 'Mawlamyine Weekend Escape', '2D1N Mon State short break package.', 165000.00, 2, '3-star hotel', 'Tour van', 'Yangon - Kyaikhto - Mawlamyine', 'Day 1 overland transfer and sightseeing. Day 2 local market and return.', 'Hotel, transport, guide', 'Meals and entrance fees not stated', NULL, 'active', '2026-04-09 12:29:49', '2026-04-09 12:29:49'),
(10, 10, 'Taunggyi - Inle Explorer', '2D1N shuttle plus guided lake package.', 198000.00, 2, 'Lake area hotel', 'Bus + boat', 'Naypyidaw - Taunggyi - Inle', 'Day 1 transfer to Taunggyi and evening market. Day 2 Inle boating and return.', 'Transport, guide, hotel, breakfast', 'Personal expense', NULL, 'active', '2026-04-09 12:29:49', '2026-04-09 12:29:49'),
(11, 10, 'Naypyidaw - Taunggyi Scenic Tour', '3D2N highland scenic package.', 265000.00, 3, '3-star mountain hotel', 'VIP coach', 'Naypyidaw - Taunggyi - local sights', 'Day 1 depart. Day 2 sightseeing. Day 3 return.', 'Hotel, transport, guide, breakfast', 'Lunch, dinner, personal expense', NULL, 'active', '2026-04-09 12:29:49', '2026-04-09 12:29:49'),
(12, 9, 'Bagan Heritage Tour Package', 'Enjoy a relaxing trip to Bagan and explore famous pagodas, ancient temples, local markets, and beautiful sunset views. This package is suitable for families, friends, and couples.', 250000.00, 3, '2 nights stay at a standard hotel in Bagan. Breakfast included.', 'Air-conditioned express bus from Yangon to Bagan and return trip included.', NULL, 'Day 1: Depart from Yangon and arrive in Bagan. Hotel check-in and visit Shwezigon Pagoda.\r\nDay 2: Visit Ananda Temple, Dhammayangyi Temple, local market, and sunset viewpoint.\r\nDay 3: Breakfast, free time, and return to Yangon.', 'Bus tickets, hotel accommodation, breakfast, tour guide, entrance fees, and local transportation.', 'Personal expenses, lunch, dinner, travel insurance, and extra activities.', 'uploads/tour_packages/tour_1782294390_85980ddf.jpg', 'active', '2026-06-24 09:46:30', '2026-06-24 09:46:30'),
(13, 8, 'Ngapali Beach Relaxation', 'Enjoy a peaceful beach holiday in Ngapali with relaxing seaside views, fresh seafood, and free time for swimming and sightseeing.', 320000.00, 3, '2 nights stay at a comfortable beach hotel near Ngapali Beach with breakfast included.', 'Round-trip express bus transportation and local hotel transfer are included.', NULL, 'Day 1: Travel to Ngapali, hotel check-in, beach relaxation.\r\nDay 2: Free time at the beach, seafood lunch, sunset view.\r\nDay 3: Morning beach walk and return trip.', 'Transportation, hotel accommodation, breakfast, local transfer, tour arrangement.', 'Personal expenses, lunch and dinner, water activities, travel insurance.', 'uploads/tour_packages/tour_1782917501_88e4ecdb.jpg', 'active', '2026-07-01 14:51:41', '2026-07-01 14:51:41');
